import './engineering-ocean.mjs?v=0.8.1';

const stage=document.querySelector('#page-engineering .ocean-stage');
stage.insertAdjacentHTML('beforeend',`<div class="sea-rotor-assembly" role="img" aria-label="缓慢旋转的三叶片风轮，原理动画示意"><svg viewBox="0 0 640 640" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="rotor-blade-metal" x1="0" x2="1" y1="0" y2=".2"><stop stop-color="#738b9d"/><stop offset=".27" stop-color="#c7d5df"/><stop offset=".5" stop-color="#f1f6f9"/><stop offset=".75" stop-color="#d5e0e7"/><stop offset="1" stop-color="#91a7b7"/></linearGradient><radialGradient id="rotor-hub-metal" cx=".33" cy=".25" r=".8"><stop stop-color="#f5fafb"/><stop offset=".5" stop-color="#d2e0e7"/><stop offset=".8" stop-color="#8ca4b5"/><stop offset="1" stop-color="#405e75"/></radialGradient><g id="sea-rotor-blade"><path d="M310 307C302 288 304 267 312 246C320 218 325 185 329 151L340 24Q341 11 345 6Q348 9 347 24L341 159C339 194 335 225 333 248Q332 281 328 308Z" fill="url(#rotor-blade-metal)" stroke="#bbcfdb" stroke-width=".55"/><path d="M316 294Q314 270 322 239Q331 194 337 91" fill="none" stroke="#f7fdff" stroke-width=".9" opacity=".8"/><path d="M309 277Q319 273 332 280M312 251Q321 247 333 252" fill="none" stroke="#8da5b5" stroke-width=".6" opacity=".65"/><path d="M311 304 310 294Q320 288 330 296L328 308" fill="#b9ccd7" stroke="#7d98ab" stroke-width=".6"/></g></defs><g class="sea-rotor-spin"><use href="#sea-rotor-blade"/><use href="#sea-rotor-blade" transform="rotate(120 320 320)"/><use href="#sea-rotor-blade" transform="rotate(240 320 320)"/><circle cx="320" cy="320" r="22" fill="url(#rotor-hub-metal)" stroke="#5f7d91" stroke-width="1"/><circle cx="320" cy="320" r="15" fill="url(#rotor-hub-metal)" stroke="#e2edf2" stroke-width="1"/><circle cx="320" cy="320" r="7" fill="#cedde5" stroke="#8ca8ba" stroke-width=".7"/><g fill="#7392a6"><circle cx="320" cy="309" r="1.3"/><circle cx="310.5" cy="325.5" r="1.3"/><circle cx="329.5" cy="325.5" r="1.3"/></g></g></svg></div><button class="sea-rotor-toggle" type="button" aria-pressed="false">暂停叶轮 <span>Ⅱ</span></button>`);
const rotor=stage.querySelector('.sea-rotor-assembly'),toggle=stage.querySelector('.sea-rotor-toggle');
let paused=matchMedia('(prefers-reduced-motion:reduce)').matches;
function update(){rotor.classList.toggle('is-paused',paused);toggle.setAttribute('aria-pressed',String(paused));toggle.innerHTML=paused?'启动叶轮 <span>▷</span>':'暂停叶轮 <span>Ⅱ</span>';}
toggle.addEventListener('click',()=>{paused=!paused;update();});update();
let inView=true;
function idle(){rotor.classList.toggle('is-idle',document.hidden||!inView);}
new IntersectionObserver(entries=>{inView=entries[0].isIntersecting;idle();},{threshold:.01}).observe(rotor);
document.addEventListener('visibilitychange',idle);
